import {TaskContext,type Component} from '@exactjs/core';

export function Document(this:Component<{page:{title:string;body:string};visible:boolean}>,props:{field:'title'|'body'}){
 this.state.page={title:'Initial',body:'loading'};this.state.visible=false;

 const load=async (_task:TaskContext=TaskContext.server().blocking())=>{await Promise.resolve();this.state.page.body="ready";};
 load();
 return ()=><html><head><title>{this.state.page.title}</title></head><body>{this.state.page.body}</body></html>;
}

